package com.anonyser.lavahider;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LavaHiderConfig.GROUP)
public interface LavaHiderConfig extends Config
{
	String GROUP = "lavahider";

	@ConfigItem(
		keyName = "showCover",
		name = "Cover lava tiles",
		description = "Dim the crater lava with the cover colour.",
		position = 0
	)
	default boolean showCover()
	{
		return true;
	}

	@Alpha
	@ConfigItem(
		keyName = "fillColor",
		name = "Cover colour",
		description = "Colour painted over the lava. Lower the alpha to dim less; raise it to hide"
			+ "<br>the lava completely.",
		position = 1
	)
	default Color fillColor()
	{
		return new Color(39, 39, 39, 155);
	}
}

package com.anonyser.lavahider;

import com.google.common.collect.Multimap;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Paints the bundled lava tiles with the configured cover colour.
 */
class LavaHiderOverlay extends Overlay
{
	private static final int MAX_DRAW_DISTANCE = 104;

	private final Client client;
	private final LavaHiderConfig config;
	private final LavaHiderPlugin plugin;

	LavaHiderOverlay(Client client, LavaHiderConfig config, LavaHiderPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showCover())
		{
			return null;
		}

		final Multimap<WorldView, WorldPoint> points = plugin.getPoints();
		if (points.isEmpty())
		{
			return null;
		}

		graphics.setColor(config.fillColor());
		for (WorldView wv : points.keySet())
		{
			for (final WorldPoint point : points.get(wv))
			{
				if (point.getPlane() != wv.getPlane())
				{
					continue;
				}

				drawTile(graphics, wv, point);
			}
		}

		return null;
	}

	private void drawTile(Graphics2D graphics, WorldView wv, WorldPoint point)
	{
		if (client.getLocalPlayer() != null && client.getLocalPlayer().getWorldView().isTopLevel())
		{
			WorldPoint playerLocation = client.getLocalPlayer().getWorldLocation();
			if (point.distanceTo(playerLocation) >= MAX_DRAW_DISTANCE)
			{
				return;
			}
		}

		LocalPoint lp = LocalPoint.fromWorld(wv, point);
		if (lp == null)
		{
			return;
		}

		Polygon poly = Perspective.getCanvasTilePoly(client, lp);
		if (poly != null)
		{
			graphics.fill(poly);
		}
	}
}

package com.anonyser.lavahider;

import com.google.common.collect.ArrayListMultimap;
import com.google.common.collect.ListMultimap;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.google.inject.Provides;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.stream.Collectors;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.WorldViewLoaded;
import net.runelite.api.events.WorldViewUnloaded;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Locked build: the lava pack ships baked into the plugin (lavapack.json) and is painted with the
 * configurable cover colour. No marking, no sharing, no dev tooling.
 */
@PluginDescriptor(
	name = "BH Lava Dimmer",
	description = "Hand placed tiles to dim anywhere in Bounty Hunter there's lava. Color slider to"
		+ " change opacity and color if wanted.",
	tags = {"lava", "bh", "bounty", "hunter", "overlay", "dim"}
)
public class LavaHiderPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(LavaHiderPlugin.class);

	private final Map<Integer, List<LavaTilePoint>> pack = new HashMap<>();
	private final ListMultimap<WorldView, WorldPoint> points = ArrayListMultimap.create();

	@Inject
	private Client client;

	@Inject
	private LavaHiderConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private Gson gson;

	private LavaHiderOverlay overlay;

	@Provides
	LavaHiderConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LavaHiderConfig.class);
	}

	@Override
	protected void startUp()
	{
		if (pack.isEmpty())
		{
			loadPack();
		}
		overlay = new LavaHiderOverlay(client, config, this);
		overlayManager.add(overlay);
		loadPoints();
	}

	@Override
	protected void shutDown()
	{
		if (overlay != null)
		{
			overlayManager.remove(overlay);
		}
		overlay = null;
		points.clear();
	}

	ListMultimap<WorldView, WorldPoint> getPoints()
	{
		return points;
	}

	private void loadPack()
	{
		try (Reader in = new InputStreamReader(
			Objects.requireNonNull(LavaHiderPlugin.class.getResourceAsStream("lavapack.json")),
			StandardCharsets.UTF_8))
		{
			// CHECKSTYLE:OFF
			List<LavaTilePoint> tiles = gson.fromJson(in, new TypeToken<List<LavaTilePoint>>(){}.getType());
			// CHECKSTYLE:ON
			for (LavaTilePoint tile : tiles)
			{
				pack.computeIfAbsent(tile.getRegionId(), k -> new ArrayList<>()).add(tile);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("failed to load the bundled lava pack", e);
		}
	}

	Collection<LavaTilePoint> getSavedPoints(int regionId)
	{
		return pack.getOrDefault(regionId, Collections.emptyList());
	}

	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		loadPoints(event.getWorldView());
	}

	@Subscribe
	public void onWorldViewUnloaded(WorldViewUnloaded event)
	{
		points.removeAll(event.getWorldView());
	}

	void loadPoints()
	{
		points.clear();

		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		loadPoints(wv);

		for (WorldEntity we : wv.worldEntities())
		{
			loadPoints(we.getWorldView());
		}
	}

	void loadPoints(WorldView wv)
	{
		points.removeAll(wv);

		int[] regions = wv.getMapRegions();
		if (regions == null)
		{
			return;
		}

		for (int regionId : regions)
		{
			Collection<LavaTilePoint> regionPoints = getSavedPoints(regionId);
			if (regionPoints.isEmpty())
			{
				continue;
			}

			// Translate region-stored tiles to world points in this world view, accounting for
			// instances (one template tile can appear at several instanced locations).
			Collection<WorldPoint> translated = regionPoints.stream()
				.map(LavaTilePoint::toWorldPoint)
				.flatMap(wp -> WorldPoint.toLocalInstance(wv, wp).stream())
				.collect(Collectors.toList());
			points.putAll(wv, translated);
		}
	}
}

package com.anonyser.lavahider;

import java.util.Objects;
import net.runelite.api.coords.WorldPoint;

/**
 * One saved lava tile, stored by region coordinates (regionId + regionX/regionY + plane) so it
 * survives instancing: the same crater instance always maps back to the same template region.
 * No per-tile colour -- the whole pack is painted with the one configured cover colour.
 */
final class LavaTilePoint
{
	private final int regionId;
	private final int regionX;
	private final int regionY;
	private final int z;

	LavaTilePoint(int regionId, int regionX, int regionY, int z)
	{
		this.regionId = regionId;
		this.regionX = regionX;
		this.regionY = regionY;
		this.z = z;
	}

	static LavaTilePoint fromWorldPoint(WorldPoint worldPoint)
	{
		return new LavaTilePoint(worldPoint.getRegionID(), worldPoint.getRegionX(), worldPoint.getRegionY(),
			worldPoint.getPlane());
	}

	WorldPoint toWorldPoint()
	{
		return WorldPoint.fromRegion(regionId, regionX, regionY, z);
	}

	int getRegionId()
	{
		return regionId;
	}

	int getRegionX()
	{
		return regionX;
	}

	int getRegionY()
	{
		return regionY;
	}

	int getZ()
	{
		return z;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof LavaTilePoint))
		{
			return false;
		}
		LavaTilePoint that = (LavaTilePoint) o;
		return regionId == that.regionId && regionX == that.regionX && regionY == that.regionY && z == that.z;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(regionId, regionX, regionY, z);
	}

	@Override
	public String toString()
	{
		return "LavaTilePoint(region=" + regionId + ", x=" + regionX + ", y=" + regionY + ", z=" + z + ")";
	}
}

package com.anonyser.lavahider;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/**
 * Play launcher: run a RuneLite client with Lava Hider loaded and NO debug logging, for smooth
 * gameplay / testing. Same as {@link LavaHiderPluginTest} but it does not route log.debug
 * anywhere, so nothing is written to disk.
 */
public class LavaHiderPlay
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LavaHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.anonyser.lavahider;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.slf4j.LoggerFactory;

/**
 * Dev launcher: run a RuneLite client (4 GB heap via the runClient task) with Lava Hider loaded,
 * and route its [lava] debug lines somewhere greppable. Which slf4j backend answers depends on the
 * test classpath (RuneLite's logback or the slf4j-simple test dependency), so cover both: under
 * simple, lines land in ~/.runelite/lavahider-dev.log (properties must be set before the first
 * logger is created); under logback, the properties are inert and the lines go to the client log.
 */
public class LavaHiderPluginTest
{
	public static void main(String[] args) throws Exception
	{
		System.setProperty("org.slf4j.simpleLogger.log.com.anonyser", "debug");
		System.setProperty("org.slf4j.simpleLogger.logFile",
			System.getProperty("user.home") + "/.runelite/lavahider-dev.log");
		final org.slf4j.Logger logger = LoggerFactory.getLogger("com.anonyser");
		if (logger instanceof Logger)
		{
			((Logger) logger).setLevel(Level.DEBUG);
		}
		ExternalPluginManager.loadBuiltin(LavaHiderPlugin.class);
		RuneLite.main(args);
	}
}

package com.anonyser.lavahider;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.List;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LavaPackTest
{
	@Test
	public void bundledPackParsesAndIsSubstantial() throws Exception
	{
		try (Reader in = new InputStreamReader(
			LavaHiderPlugin.class.getResourceAsStream("lavapack.json"), StandardCharsets.UTF_8))
		{
			assertNotNull(in);
			List<LavaTilePoint> tiles = new Gson().fromJson(in, new TypeToken<List<LavaTilePoint>>()
			{
			}.getType());

			assertNotNull(tiles);
			assertTrue("pack should hold the marked crater", tiles.size() > 1000);
			// Every entry must survive the region round trip (valid coordinates).
			for (LavaTilePoint tile : new HashSet<>(tiles))
			{
				assertTrue(tile.getRegionX() >= 0 && tile.getRegionX() < 64);
				assertTrue(tile.getRegionY() >= 0 && tile.getRegionY() < 64);
			}
		}
	}
}

package com.anonyser.lavahider;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LavaTilePointTest
{
	@Test
	public void equalsMatchesOnAllCoordinates()
	{
		LavaTilePoint a = new LavaTilePoint(12856, 10, 20, 0);
		LavaTilePoint same = new LavaTilePoint(12856, 10, 20, 0);
		assertEquals(a, same);
		assertEquals(a.hashCode(), same.hashCode());

		assertNotEquals(a, new LavaTilePoint(12857, 10, 20, 0));
		assertNotEquals(a, new LavaTilePoint(12856, 11, 20, 0));
		assertNotEquals(a, new LavaTilePoint(12856, 10, 21, 0));
		assertNotEquals(a, new LavaTilePoint(12856, 10, 20, 1));
	}

	@Test
	public void gsonRoundTripPreservesEveryTile()
	{
		Gson gson = new Gson();
		List<LavaTilePoint> pack = Arrays.asList(
			new LavaTilePoint(12856, 0, 0, 0),
			new LavaTilePoint(12856, 63, 63, 0),
			new LavaTilePoint(13112, 5, 40, 1));

		String json = gson.toJson(pack);
		List<LavaTilePoint> back = gson.fromJson(json, new TypeToken<List<LavaTilePoint>>()
		{
		}.getType());

		assertEquals(pack, back);
	}

	@Test
	public void worldPointRoundTripKeepsRegionCoordinates()
	{
		LavaTilePoint point = new LavaTilePoint(12856, 17, 42, 0);
		assertEquals(point, LavaTilePoint.fromWorldPoint(point.toWorldPoint()));
	}
}
